import pytest
from candidate import remove_duplicates

def test_remove_duplicates_no_duplicates():
    assert remove_duplicates([1, 2, 3]) == [1, 2, 3]

def test_remove_duplicates_one_duplicate():
    assert remove_duplicates([1, 1, 2, 2, 3]) == [2, 3]

def test_remove_duplicates_multiple_duplicates():
    assert remove_duplicates([1, 2, 2, 3, 3, 3, 4]) == [1, 4]

def test_remove_duplicates_empty_list():
    assert remove_duplicates([]) == []

def test_remove_duplicates_all_duplicates():
    assert remove_duplicates([1, 1, 1, 2, 2, 2]) == []

def test_remove_duplicates_one_element():
    assert remove_duplicates([1]) == [1]

def test_remove_duplicates_single_element():
    assert remove_duplicates([1, 1]) == []

def test_remove_duplicates_large_numbers():
    assert remove_duplicates([10, 20, 20, 30, 30, 30, 40]) == [10, 40]

def test_remove_duplicates_negative_numbers():
    assert remove_duplicates([-1, -2, -3, -2, -4]) == [-1, -3, -4]

def test_remove_duplicates_mixed_numbers():
    assert remove_duplicates([1, -1, 2, -2, 3, -3]) == [1, 2, 3]

def test_remove_duplicates_none_input():
    with pytest.raises(TypeError):
        remove_duplicates(None)

def test_remove_duplicates_non_list_input():
    with pytest.raises(TypeError):
        remove_duplicates("not a list")

def test_remove_duplicates_non_integer_elements():
    with pytest.raises(TypeError):
        remove_duplicates([1, "a", 2, "b", 3])
